head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.trigger_onclick = function(e) {
    multiupload.setTitleInput("abc")
};
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger').click()");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('multiupload_file_input').getAttribute('title') == 'abc'", "true");
    WebSquare.wUnit.addCommand('pause', '500');
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
